"""Code-native store posters: exact logo and unmodified Flutter screen captures."""
from pathlib import Path
import html
import shutil

root = Path(__file__).resolve().parents[2]
out = root / 'output/store-assets'
out.mkdir(parents=True, exist_ok=True)
for source, name in [('logo.png', 'qazaqmetal-logo.png'), ('Manrope.ttf', 'Manrope.ttf'), ('PTSerif-Bold.ttf', 'PTSerif-Bold.ttf')]:
    shutil.copy2(root / 'platform/client/assets' / source, out / name)
for license_name in ('Manrope-OFL.txt', 'PTSerif-OFL.txt'):
    shutil.copy2(root / 'platform/client/assets' / license_name, out / license_name)
posters = [
    ('member-01', 'QMET+', 'Выгодно быть<br>вместе', 'Привилегии вашего профсоюза', 'member', 'Цифровая карта участника'),
    ('member-02', 'QMET+', 'Ваши партнёры.<br>Ваши привилегии.', 'Заведения и условия предложений', 'member-1', 'Сохраняйте любимые места'),
    ('member-03', 'QMET+', 'Всё важное —<br>в вашем профиле.', 'Карта, история и поддержка', 'member-4', 'Удобно каждый день'),
    ('partner-01', 'QMET+ Партнёр', 'Ваш бизнес.<br>В одном приложении.', 'Заведения · Предложения · Статистика', 'partner', 'Кабинет партнёра'),
    ('partner-02', 'QMET+ Партнёр', 'Ваше заведение.<br>В центре внимания.', 'Управляйте информацией о заведениях', 'partner-1', 'Информация для участников клуба'),
    ('partner-03', 'QMET+ Партнёр', 'Работать вместе<br>ещё удобнее.', 'Ваш кабинет и связь с поддержкой', 'partner-4', 'Для сотрудников партнёров'),
]
css = '''@font-face{font-family:Manrope;src:url(Manrope.ttf)}@font-face{font-family:Serif;src:url(PTSerif-Bold.ttf);font-weight:700}*{box-sizing:border-box}html,body{margin:0;width:1320px;height:2868px;overflow:hidden}body{background:#f8f3ef;color:#25192f;font-family:Manrope,sans-serif}.poster{position:relative;width:1320px;height:2868px;overflow:hidden;background:radial-gradient(ellipse at 75% 28%,#fffcf9,transparent 60%),linear-gradient(140deg,#f4e8e5,#fffaf7 60%,#e4d3df)}.brand{position:absolute;left:105px;top:90px;display:flex;align-items:center;gap:30px;font-size:62px;font-weight:800;letter-spacing:-2px}.brand img{width:124px;height:124px;object-fit:contain;border-radius:50%;background:white}h1{position:absolute;left:105px;top:260px;margin:0;font:700 112px/1.07 Serif,serif;letter-spacing:-2px;max-width:1130px}h1 span{color:#6e2ebd}.subtitle{position:absolute;top:565px;left:110px;max-width:1080px;font-size:39px;color:#66546f;line-height:1.5}.line{position:absolute;top:680px;left:110px;width:135px;height:9px;background:#6e2ebd;border-radius:20px}.ribbon{position:absolute;left:-400px;top:1570px;width:2200px;height:430px;transform:rotate(-27deg);border-radius:48% 24% 48% 24%;background:linear-gradient(174deg,#d8b2e4 0%,#b677d0 17%,#7932a8 42%,#3f135e 67%,#ac71c4 84%,#ddbbe5 100%);box-shadow:0 50px 80px #4f285638,inset 0 7px 14px #ffffff88}.shadow{position:absolute;left:160px;top:2580px;width:1030px;height:115px;border-radius:50%;background:#311c48;filter:blur(55px);opacity:.21}.phone{position:absolute;left:266px;top:835px;width:820px;padding:20px;border-radius:105px;background:linear-gradient(120deg,#c3b4bd,#252027 7%,#09090b 55%,#a89caa 94%,#3a343b);box-shadow:18px 18px 0 #41333f,35px 38px 40px #32233766;transform:perspective(3400px) rotateY(-9deg) rotateZ(5deg);transform-origin:center}.phone:after{content:'';position:absolute;right:-15px;top:430px;width:9px;height:160px;background:#766877;border-radius:8px}.screen{display:block;width:780px;height:auto;aspect-ratio:440/956;object-fit:contain;border:7px solid #0e0c10;border-radius:86px;background:#f8f3ef}.caption{position:absolute;left:108px;top:2735px;right:105px;display:flex;align-items:center;justify-content:space-between;font-size:28px;color:#62526a}.caption strong{font-weight:700}.caption small{font-size:20px;letter-spacing:1px}.pill{position:absolute;top:751px;left:110px;font-size:23px;letter-spacing:5px;color:#876597;text-transform:uppercase}'''
for slug, brand, heading, subtitle, screen, caption in posters:
    document = f'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><title>{brand} — {caption}</title><style>{css}</style></head><body><main class="poster"><div class="brand"><img src="qazaqmetal-logo.png" alt="QAZAQMETAL KÁSIPODAǴY"><span>{brand}</span></div><h1>{heading}</h1><div class="subtitle">{html.escape(subtitle)}</div><div class="line"></div><div class="pill">{html.escape(caption)}</div><div class="ribbon"></div><div class="shadow"></div><div class="phone"><img class="screen" src="screens/{screen}.png" alt="Реальный интерфейс приложения; демонстрационные данные"></div><footer class="caption"><strong>Выгодно быть вместе</strong><small>ДЕМОНСТРАЦИОННЫЕ ДАННЫЕ</small></footer></main></body></html>'''
    (out / (slug + '.html')).write_text(document)
    google = '''html,body,.poster{width:1080px;height:1920px}.brand{top:62px;left:76px;font-size:48px;gap:23px}.brand img{width:96px;height:96px}h1{top:205px;left:76px;font-size:88px;max-width:940px}.subtitle{top:450px;left:80px;font-size:29px;max-width:920px}.line{top:540px;left:80px;width:110px;height:7px}.pill{top:590px;left:80px;font-size:19px;letter-spacing:3px}.phone{left:305px;top:680px;width:520px;padding:13px;border-radius:73px}.screen{width:494px;border-radius:59px;border-width:5px}.phone:after{top:260px;height:110px}.ribbon{top:1200px;left:-350px;width:1800px;height:315px}.shadow{top:1780px;left:210px;width:660px;height:70px;filter:blur(40px)}.caption{top:1855px;left:80px;right:70px;font-size:22px}.caption small{font-size:15px}'''
    (out / (slug + '-google.html')).write_text(document.replace('</style>', google + '</style>'))
    if slug.endswith('-01'):
        feature = '''html,body,.poster{width:1024px;height:500px}.brand{top:32px;left:42px;font-size:32px;gap:16px;letter-spacing:-1px}.brand img{width:65px;height:65px}h1{top:134px;left:42px;font-size:63px;max-width:610px}.subtitle{top:354px;left:46px;font-size:23px;max-width:590px}.line{top:426px;left:46px;width:80px;height:5px}.pill,.caption,.shadow{display:none}.phone{left:720px;top:22px;width:210px;padding:7px;border-radius:28px;box-shadow:5px 5px 0 #41333f,12px 14px 22px #32233744}.screen{width:196px;border-radius:23px;border-width:2px}.phone:after{display:none}.ribbon{top:310px;left:500px;width:950px;height:140px}'''
        (out / (slug.split('-')[0] + '-feature.html')).write_text(document.replace('</style>', feature + '</style>'))
gallery = ''.join(f'<a href="{slug}.html"><img src="{slug}.jpg" alt="{brand}"><b>{slug}</b></a>' for slug, brand, *_ in posters)
(out / 'index.html').write_text(f'''<!doctype html><html lang="ru"><meta charset="utf-8"><title>QMET+ · Креативы для согласования</title><style>body{{margin:35px;background:#f8f3ef;font:18px system-ui;color:#25192f}}h1{{font-size:34px}}.grid{{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}}a{{display:block;overflow:hidden;border-radius:18px;background:#eadde7;text-decoration:none;color:#25192f}}img{{width:100%;display:block}}b{{display:block;padding:12px 20px}}</style><h1>QMET+ · Серия для согласования</h1><p>Логотип QAZAQMETAL из репозитория. Реальные экраны приложения с демонстрационными данными.</p><div class="grid">{gallery}</div></html>''')
print('Created', len(posters), 'store posters (1320 × 2868) and approval gallery')
